def classify_incident(users_affected, service_down, has_workaround):
    if not users_affected:
        return "SEV-4"  # Internal, no user impact
    if service_down and not has_workaround:
        return "SEV-1"  # Complete outage, no workaround
    if service_down and has_workaround:
        return "SEV-2"  # Degraded with workaround
    return "SEV-3"  # Minor issue

# Examples
print(classify_incident(True, True, False))  # SEV-1
print(classify_incident(True, True, True))   # SEV-2
print(classify_incident(False, True, False)) # SEV-4

