def should_allow_request(cb):
    if cb.state == "open":
        if time_since_trip() > cb.recovery_seconds:
            cb.state = "half-open"
            return cb.half_open_requests > 0
        return False
    return True

CRISIS_CRITERIA = [
    "All user data compromised",
    "Platform down for more than 4 hours",
    "Regulatory fine risk above $1M",
    "Media coverage in major outlets",
    "Competitor advantage from outage"
]

def should_activate_crisis(incident):
    return any(criterion in incident.tags for criterion in CRISIS_CRITERIA)
